**ECS Implementation**:
```typescript
// Component for active card effects
interface CardEffectComponent {
  cardId: string;
  modifiers: Modifier[];
  startTime: number;
  duration: number;
  isActive: boolean;
}

// System that applies modifiers to physics params
class CardEffectSystem {
  private baseParams: PhysicsParameters;
  private currentParams: PhysicsParameters;
  private activeEffects: Map<string, CardEffectComponent> = new Map();

  applyCard(card: CardData, entity: Entity): void {
    const effect: CardEffectComponent = {
      cardId: card.id,
      modifiers: card.modifiers,
      startTime: this.simulationTime,
      duration: card.duration,
      isActive: true,
    };
    this.activeEffects.set(card.id + '_' + Date.now(), effect);
    this.recalculateParameters();
  }

  private recalculateParameters(): void {
    this.currentParams = { ...this.baseParams };
    for (const effect of this.activeEffects.values()) {
      if (!effect.isActive) continue;
      for (const mod of effect.modifiers) {
        const current = this.currentParams[mod.target] ?? 1.0;
        switch (mod.operation) {
          case 'multiply': this.currentParams[mod.target] = current * mod.value; break;
          case 'add': this.currentParams[mod.target] = current + mod.value; break;
          case 'set': this.currentParams[mod.target] = mod.value; break;
        }
      }
    }
    // Apply to vehicle
    this.vehicle.chassisBody.mass = this.currentParams.mass;
    this.updateWheelFriction();
  }

  update(dt: number): void {
    for (const [key, effect] of this.activeEffects) {
      if (this.simulationTime - effect.startTime >= effect.duration) {
        effect.isActive = false;
        this.activeEffects.delete(key);
        this.recalculateParameters();
      }
    }
  }
}
```

**Deck Management**:
- Deck size: 15-20 cards
- Hand size: 5 cards
- Draw rate: 1 card per 8 seconds + 1 on drift score milestone
- Energy system: Cards cost "Focus" (regenerates 1/sec, max 10)
- Mulligan: Once per run, reshuffle hand

### 5. Drift Scoring System

**Score Components**:
```typescript
interface DriftScoreState {
  angle: number;           // Current slip angle (rad)
  speed: number;           // Current speed (m/s)
  duration: number;        // Time in current drift (s)
  comboMultiplier: number; // Increases with sustained drift
  nearMisses: number;      // Close to walls/objects
  zonesHit: number;        // Designated drift zones
}

function calculateDriftScore(state: DriftScoreState): number {
  const angleScore = Math.min(state.angle / 0.8, 1.5) * 100; // Peak at ~45°
  const speedScore = Math.min(state.speed / 30, 1.0) * 50;   // Peak at 108 km/h
  const durationBonus = Math.min(state.duration * 10, 500);
  const nearMissBonus = state.nearMisses * 200;
  const zoneBonus = state.zonesHit * 500;

  return Math.floor((angleScore + speedScore + durationBonus + nearMissBonus + zoneBonus) * state.comboMultiplier);
}
```

**Drift Detection**:
```typescript
function updateDriftState(vehicle: Vehicle, dt: number): void {
  const rearSlip = Math.max(
    Math.abs(vehicle.wheelSlipAngles[2]),
    Math.abs(vehicle.wheelSlipAngles[3])
  );
  const frontSlip = Math.max(
    Math.abs(vehicle.wheelSlipAngles[0]),
    Math.abs(vehicle.wheelSlipAngles[1])
  );

  const isDrifting = rearSlip > 0.15 && rearSlip > frontSlip * 1.2 && vehicle.speed > 5;

  if (isDrifting) {
    driftState.duration += dt;
    driftState.angle = rearSlip;
    driftState.speed = vehicle.speed;
    driftState.comboMultiplier = Math.min(1 + driftState.duration * 0.1, 5.0);
  } else {
    // Drift ended - bank score
    if (driftState.duration > 0.5) {
      totalScore += calculateDriftScore(driftState);
      spawnScorePopup(calculateDriftScore(driftState));
    }
    resetDriftState();
  }
}
```

### 6. Visual Effects

**Tire Smoke (GPU Particle System)**:
```glsl
// tireSmoke.vert
attribute vec3 position;
attribute float startTime;
attribute float life;
attribute vec3 velocity;
uniform float currentTime;
uniform mat4 projectionMatrix;
uniform mat4 modelViewMatrix;
varying float vAlpha;
varying vec3 vColor;

void main() {
  float age = currentTime - startTime;
  if (age > life) {
    gl_Position = vec4(0,0,0,0);
    return;
  }

  float progress = age / life;
  vec3 pos = position + velocity * age + vec3(0, 0.5 * age * age, 0); // rise
  pos.x += sin(age * 5.0 + position.x * 10.0) * 0.1 * progress; // turbulence
  pos.z += cos(age * 3.0 + position.z * 10.0) * 0.1 * progress;

  vAlpha = 1.0 - progress;
  vColor = mix(vec3(0.9, 0.9, 0.95), vec3(0.3, 0.3, 0.35), progress);

  vec4 mvPosition = modelViewMatrix * vec4(pos, 1.0);
  gl_PointSize = (150.0 / -mvPosition.z) * (1.0 + progress * 2.0);
  gl_Position = projectionMatrix * mvPosition;
}
```

