### 7. Input Handling

**Keyboard with Steering Assist**:
```typescript
class InputManager {
  private keys = new Set<string>();
  private steerInput = 0;
  private targetSteer = 0;
  private steerRate = 3.0; // rad/s
  private counterSteerAssist = 0.3;

  constructor() {
    window.addEventListener('keydown', e => this.keys.add(e.code));
    window.addEventListener('keyup', e => this.keys.delete(e.code));
  }

  update(dt: number, vehicle: Vehicle): void {
    // Throttle/Brake
    const throttle = this.keys.has('ArrowUp') || this.keys.has('KeyW') ? 1 : 0;
    const brake = this.keys.has('ArrowDown') || this.keys.has('KeyS') ? 1 : 0;
    const handbrake = this.keys.has('Space') ? 1 : 0;

    // Steering with rate limiting
    let target = 0;
    if (this.keys.has('ArrowLeft') || this.keys.has('KeyA')) target = -1;
    if (this.keys.has('ArrowRight') || this.keys.has('KeyD')) target = 1;

    this.targetSteer = target;

    // Counter-steer assist: when drifting, help player counter-steer
    const slipAngle = vehicle.getRearSlipAngle();
    if (Math.abs(slipAngle) > 0.2 && Math.sign(slipAngle) !== Math.sign(this.targetSteer)) {
      this.targetSteer += Math.sign(slipAngle) * this.counterSteerAssist;
    }

    this.targetSteer = THREE.MathUtils.clamp(this.targetSteer, -1, 1);

    // Rate-limited steering
    const maxDelta = this.steerRate * dt;
    if (this.targetSteer > this.steerInput) this.steerInput = Math.min(this.steerInput + maxDelta, this.targetSteer);
    else if (this.targetSteer < this.steerInput) this.steerInput = Math.max(this.steerInput - maxDelta, this.targetSteer);

    // Apply to vehicle
    vehicle.setSteer(this.steerInput * vehicle.maxSteerAngle);
    vehicle.setThrottle(throttle);
    vehicle.setBrake(brake);
    vehicle.setHandbrake(handbrake);
  }
}
```

**Gamepad Support**:
```typescript
function applyGamepadCurve(input: number, deadzone: number = 0.1, exponent: number = 1.5): number {
  if (Math.abs(input) < deadzone) return 0;
  const sign = Math.sign(input);
  const normalized = (Math.abs(input) - deadzone) / (1 - deadzone);
  return sign * Math.pow(normalized, exponent);
}
```

### 8. Networking Architecture (Future Multiplayer)

**Deterministic Fixed Timestep**:
```typescript
const FIXED_DT = 1/60; // 60 Hz physics
let accumulator = 0;

function gameLoop(frameTime: number): void {
  accumulator += frameTime;
  while (accumulator >= FIXED_DT) {
    physicsStep(FIXED_DT);
    inputStep(FIXED_DT);
    cardEffectStep(FIXED_DT);
    driftScoreStep(FIXED_DT);
    accumulator -= FIXED_DT;
  }

  const alpha = accumulator / FIXED_DT;
  renderStep(alpha); // Interpolated render
}
```

