**Lag Compensation**: Client-side prediction with server reconciliation. Client runs physics locally, sends inputs to server. Server authoritative simulation, sends corrections. Client interpolates between server states.

## Code Examples & Patterns

### Main Game Loop Structure
```typescript
class Game {
  private renderer: THREE.WebGLRenderer;
  private scene: THREE.Scene;
  private camera: THREE.PerspectiveCamera;
  private physicsWorld: CANNON.World;
  private vehicle: DriftVehicle;
  private input: InputManager;
  private cardSystem: CardSystem;
  private driftScoring: DriftScoringSystem;
  private tireMarks: TireMarkSystem;
  private tireSmoke: TireSmokeSystem;
  private ui: GameUI;

  private lastTime = 0;
  private fixedAccumulator = 0;

  async init(): Promise<void> {
    // Initialize renderer
    this.renderer = new THREE.WebGLRenderer({ antialias: true });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(this.renderer.domElement);

    // Load assets
    await this.loadAssets();

    // Initialize physics
    this.physicsWorld = new CANNON.World({ gravity: new CANNON.Vec3(0, -14.7, 0) });

    // Create vehicle
    this.vehicle = new DriftVehicle(this.physicsWorld, this.scene);

    // Initialize systems
    this.input = new InputManager();
    this.cardSystem = new CardSystem(this.vehicle);
    this.driftScoring = new DriftScoringSystem(this.vehicle);
    this.tireMarks = new TireMarkSystem(this.renderer);
    this.tireSmoke = new TireSmokeSystem(this.scene);
    this.ui = new GameUI(this.cardSystem, this.driftScoring);

    // Start loop
    requestAnimationFrame(this.loop.bind(this));
  }

  private loop(time: number): void {
    const dt = Math.min((time - this.lastTime) / 1000, 0.1); // Cap at 100ms
    this.lastTime = time;

    // Fixed timestep physics
    this.fixedAccumulator += dt;
    while (this.fixedAccumulator >= FIXED_DT) {
      this.fixedStep(FIXED_DT);
      this.fixedAccumulator -= FIXED_DT;
    }

    // Interpolated render
    const alpha = this.fixedAccumulator / FIXED_DT;
    this.renderStep(alpha);

    requestAnimationFrame(this.loop.bind(this));
  }

  private fixedStep(dt: number): void {
    this.input.update(dt, this.vehicle);
    this.vehicle.update(dt);
    this.cardSystem.update(dt);
    this.driftScoring.update(dt);
    this.physicsWorld.step(dt);
    this.tireSmoke.emitFromWheels(this.vehicle);
  }

  private renderStep(alpha: number): void {
    this.vehicle.interpolateRender(alpha);
    this.tireMarks.update(this.renderer);
    this.tireSmoke.update();
    this.renderer.render(this.scene, this.camera);
    this.ui.update();
  }
}
```

### Card UI Component (React-like Vanilla JS)
```typescript
class CardUI {
  private handElement: HTMLElement;
  private deckElement: HTMLElement;
  private focusBar: HTMLElement;
  private selectedCard: CardData | null = null;

  renderHand(cards: CardData[], focus: number): void {
    this.handElement.innerHTML = cards.map((card, i) => `
      <div class="card ${card.cost > focus ? 'unaffordable' : ''} ${this.selectedCard?.id === card.id ? 'selected' : ''}"
           data-card-id="${card.id}"
           style="--rarity: ${card.rarity}">
        <div class="card-cost">${card.cost}</div>
        <div class="card-name">${card.name}</div>
        <div class="card-type">${card.type}</div>
        <div class="card-desc">${card.description}</div>
        <div class="card-duration">${card.duration}s</div>
      </div>
    `).join('');

    this.focusBar.style.width = `${(focus / 10) * 100}%`;
  }

  bindEvents(onPlayCard: (cardId: string) => void): void {
    this.handElement.addEventListener('click', e => {
      const cardEl = e.target.closest('.card');
      if (!cardEl || cardEl.classList.contains('unaffordable')) return;

      const cardId = cardEl.dataset.cardId;
      if (this.selectedCard?.id === cardId) {
        onPlayCard(cardId);
        this.selectedCard = null;
      } else {
        this.selectedCard = this.cardSystem.getCardById(cardId);
      }
      this.renderHand(this.cardSystem.getHand(), this.cardSystem.getFocus());
    });
  }
}
