## Code Examples & Patterns

### Physics-Render Synchronization Loop
```typescript
// src/core/PhysicsRenderLoop.ts
import * as CANNON from 'cannon-es';
import * as THREE from 'three';

const FIXED_TIME_STEP = 1 / 60;
const MAX_SUB_STEPS = 3;

let lastTime = performance.now();
let accumulator = 0;

function animate(currentTime: number): void {
  const deltaTime = (currentTime - lastTime) / 1000;
  lastTime = currentTime;
  accumulator += deltaTime;

  while (accumulator >= FIXED_TIME_STEP) {
    physicsWorld.step(FIXED_TIME_STEP);
    accumulator -= FIXED_TIME_STEP;
  }

  const alpha = accumulator / FIXED_TIME_STEP;
  interpolateBodies(alpha);
  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

function interpolateBodies(alpha: number): void {
  physicsBodies.forEach(({ body, mesh, prevPosition, prevQuaternion }) => {
    mesh.position.lerpVectors(prevPosition, body.position, alpha);
    mesh.quaternion.slerpQuaternions(prevQuaternion, body.quaternion, alpha);
    prevPosition.copy(body.position);
    prevQuaternion.copy(body.quaternion);
  });
}
```

### RaycastVehicle Setup with Drift Physics
```typescript
// src/vehicle/VehicleController.ts
import * as CANNON from 'cannon-es';

function createVehicle(chassisBody: CANNON.Body, config: VehicleConfig): CANNON.RaycastVehicle {
  const vehicle = new CANNON.RaycastVehicle({ chassisBody });

  // Wheel positions: FL, FR, RL, RR
  const positions = [
    new CANNON.Vec3(-config.trackWidth/2, 0, config.wheelBase/2),
    new CANNON.Vec3( config.trackWidth/2, 0, config.wheelBase/2),
    new CANNON.Vec3(-config.trackWidth/2, 0, -config.wheelBase/2),
    new CANNON.Vec3( config.trackWidth/2, 0, -config.wheelBase/2),
  ];

  positions.forEach((pos, i) => {
    const isFront = i < 2;
    vehicle.addWheel({
      localPosition: pos,
      directionLocal: new CANNON.Vec3(0, -1, 0),
      axleLocal: new CANNON.Vec3(1, 0, 0),
      suspensionStiffness: isFront ? 30 : 25,
      suspensionRestLength: 0.15,
      maxSuspensionForce: 100000,
      rollInfluence: isFront ? 0.01 : 0.0,
      radius: config.wheelRadius,
      frictionSlip: isFront ? 10.5 : 8.5, // Rear tires slip easier for drift
    });
  });

  // Custom tire friction curve for drift physics
  vehicle.wheelInfos.forEach((wheel, i) => {
    wheel.sideFriction = new CANNON.Vec3(0, 0, 0); // Handled in custom slip calc
    wheel.customSlipCalculation = calculateDriftSlip;
  });

  return vehicle;
}

function calculateDriftSlip(wheel: CANNON.WheelInfo, groundBody: CANNON.Body): number {
  const slipAngle = Math.atan2(wheel.sideImpulse, wheel.forwardImpulse);
  const driftFactor = Math.abs(slipAngle) > 0.15 ? 1.5 : 1.0; // Drift bonus grip
  return wheel.frictionSlip * driftFactor;
}
```

### Card Effect Application System
```typescript
// src/cards/CardEffectEngine.ts
import { CardEffect, CardInstance, VehicleConfig } from '@/types';

class CardEffectEngine {
  private activeEffects = new Map<string, CardInstance>();
  private vehicleConfig: VehicleConfig;

  constructor(baseConfig: VehicleConfig) {
    this.vehicleConfig = { ...baseConfig };
  }

  applyCard(card: CardEffect): void {
    const instance: CardInstance = {
      card,
      remainingCooldown: card.cooldown,
      charges: card.type === 'instant' ? 1 : Infinity,
    };
    this.activeEffects.set(card.id, instance);
    this.recalculateConfig();
  }

  update(deltaTime: number): void {
    this.activeEffects.forEach((instance, id) => {
      if (instance.card.type === 'duration') {
        instance.remainingCooldown -= deltaTime;
        if (instance.remainingCooldown <= 0) {
          this.activeEffects.delete(id);
          this.recalculateConfig();
        }
      }
      if (instance.card.type === 'instant' && instance.charges > 0) {
        instance.charges--;
        if (instance.charges === 0) this.activeEffects.delete(id);
      }
    });
  }

  private recalculateConfig(): void {
    const multipliers = { engine: 1, chassis: 1, tires: 1, driver: 1 };

    this.activeEffects.forEach(({ card }) => {
      const cat = card.params.category;
      if (cat) multipliers[cat] *= (1 + (card.params.magnitude ?? 0));
    });

    // Apply diminishing returns
    Object.keys(multipliers).forEach(k => {
      const m = multipliers[k as keyof typeof multipliers];
      multipliers[k as keyof typeof multipliers] = 1 + (m - 1) / (1 + (m - 1) * 0.1);
    });

    this.vehicleConfig.engineTorque *= multipliers.engine;
    this.vehicleConfig.rearGrip *= multipliers.tires;
    this.vehicleConfig.downforce *= multipliers.chassis;
  }
}
```

### Asset Loading with Progress Tracking
```typescript
// src/assets/AssetManager.ts
import * as THREE from 'three';

const loadingManager = new THREE.LoadingManager();
loadingManager.onProgress = (url, loaded, total) => {
  const progress = loaded / total;
  eventBus.emit('asset:progress', { progress, url });
};
loadingManager.onError = (url) => console.error(`Failed to load: ${url}`);

const textureLoader = new THREE.TextureLoader(loadingManager);
const gltfLoader = new THREE.GLTFLoader(loadingManager);

export async function loadVehicleAssets(vehicleId: string): Promise<VehicleAssets> {
  const [model, diffuse, normal, roughness, ao] = await Promise.all([
    gltfLoader.loadAsync(`/assets/vehicles/${vehicleId}/model.glb`),
    textureLoader.loadAsync(`/assets/vehicles/${vehicleId}/diffuse.jpg`),
    textureLoader.loadAsync(`/assets/vehicles/${vehicleId}/normal.jpg`),
    textureLoader.loadAsync(`/assets/vehicles/${vehicleId}/roughness.jpg`),
    textureLoader.loadAsync(`/assets/vehicles/${vehicleId}/ao.jpg`),
  ]);

  // Configure textures
  [diffuse, normal, roughness, ao].forEach(tex => {
    tex.colorSpace = tex === diffuse ? THREE.SRGBColorSpace : THREE.LinearSRGBColorSpace;
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.generateMipmaps = true;
    tex.minFilter = THREE.LinearMipmapLinearFilter;
  });

  return { model, textures: { diffuse, normal, roughness, ao } };
}
